 const attach=async(evidenceId:string)=>{setBusy(true);try{await evidenceMutation({action:'link_evidence',battle:battle.id,argumentId:argument.argumentId,evidenceId});toast.success('Feat attached to the argument.');reload()}catch(e){toast.error((e as Error).message)}finally{setBusy(false)}};
